from dataclasses import dataclass
@dataclass(frozen=True)          # frozen → 해시 가능 → 캐시 키로 쓸 수 있다
class TravelState:
    loc: int
    tickets: int
    last_tram: bool              # 트램 연속 금지 규칙용
class LimitedTravel:
    def __init__(self, n, tickets): self.n, self.t = n, tickets
    def start_state(self): return TravelState(1, self.t, False)
    def is_end(self, s): return s.loc == self.n          # 남은 표 수는 안 본다
    def successors(self, s):
        out = []
        if s.loc + 1 <= self.n:
            out.append(("walk", 1, TravelState(s.loc + 1, s.tickets, False)))
        if s.tickets > 0 and 2 * s.loc <= self.n and not s.last_tram:
            out.append(("tram", 2, TravelState(2 * s.loc, s.tickets - 1, True)))
        return out
p = LimitedTravel(10, 1)
for a, c, s in p.successors(p.start_state()): print(a, c, s)
s = TravelState(2, 1, True)      # 방금 트램을 탄 상태
print([a for a, _, _ in p.successors(s)])   # ['walk'] — 연속 트램 금지

import math
def successors(n, s):            # 교통 문제: (행동, 비용, 다음 상태)
    out = [("walk", 1, s + 1)] if s + 1 <= n else []
    if 2 * s <= n: out.append(("tram", 2, 2 * s))
    return out
def exhaustive_search(n):
    explored = 0
    def future(s):               # (비용, 행동열) = s 에서 끝까지의 최선
        nonlocal explored
        explored += 1
        if s == n: return 0, []
        best = (math.inf, None)
        for a, c, s2 in successors(n, s):
            fc, acts = future(s2)                # 남은 문제는 '남의 일'
            if c + fc < best[0]: best = (c + fc, [a] + acts)
        return best
    cost, acts = future(1)
    return cost, acts, explored
for n in [4, 10, 17, 25]:
    print(n, exhaustive_search(n))

import math
def successors(n, s):
    out = [("walk", 1, s + 1)] if s + 1 <= n else []
    if 2 * s <= n: out.append(("tram", 2, 2 * s))
    return out
def dynamic_programming(n):
    explored, cache = 0, {}                  # NEW: 상태 → 최선의 (비용, 행동열)
    def future(s):
        nonlocal explored
        if s in cache: return cache[s]       # NEW: 이미 푼 상태면 그대로
        explored += 1
        if s == n: best = (0, [])
        else:
            best = (math.inf, None)
            for a, c, s2 in successors(n, s):
                fc, acts = future(s2)
                if c + fc < best[0]: best = (c + fc, [a] + acts)
        cache[s] = best                      # NEW: 적어 둔다
        return best
    return future(1), explored, cache
(cost, acts), explored, cache = dynamic_programming(10)
print(cost, acts, explored)
print({s: cache[s][0] for s in sorted(cache)})   # 모든 상태의 미래 비용
(cost, acts), explored, _ = dynamic_programming(100)
print(cost, acts, explored)

import random
def successors(n, s):
    out = [("walk", 1, s + 1)] if s + 1 <= n else []
    if 2 * s <= n: out.append(("tram", 2, 2 * s))
    return out
def uniform_policy(n, s):                    # 정책: 상태 → 행동(무작위)
    return random.choice(successors(n, s))
def rollout(n, policy, max_steps=20):
    s, steps = 1, []
    while s != n and len(steps) < max_steps:
        step = policy(n, s)
        steps.append(step); s = step[2]
    cost = sum(c for _, c, _ in steps) if s == n else float("inf")
    return cost, [a for a, _, _ in steps]
def best_of_n(n, policy, num):
    sols = [rollout(n, policy) for _ in range(num)]   # 서로 독립 → 병렬 가능
    return min(sols)
random.seed(0)
print([rollout(10, uniform_policy)[0] for _ in range(8)])   # 굴릴 때마다 다르다
for num in [1, 3, 10, 100]:
    print(num, best_of_n(10, uniform_policy, num))

def successors(n, s):
    out = [("walk", 1, s + 1)] if s + 1 <= n else []
    if 2 * s <= n: out.append(("tram", 2, 2 * s))
    return out
def beam_search(n, beam_width, max_steps=10):
    cands = [(0, [], 1)]                     # (지금까지 비용, 행동열, 마지막 상태)
    explored = 0
    for _ in range(max_steps):
        new = []
        for cost, acts, s in cands:
            if s == n: new.append((cost, acts, s)); continue   # 끝난 것은 그대로 둔다
            for a, c, s2 in successors(n, s):
                new.append((cost + c, acts + [a], s2)); explored += 1
        new.sort(key=lambda x: x[0])         # 비용순 정렬(안정 정렬)
        cands = new[:beam_width]             # 가지치기
    done = [x for x in cands if x[2] == n]
    return (done[0] if done else None), explored
for k in [1, 2, 3, 10]:
    print(k, beam_search(10, k))
print(beam_search(17, 2), beam_search(17, 4))

import heapq
# 가중 그래프: 상태 → [(다음, 비용)]. 강의의 교통 문제도 그대로 넣을 수 있다.
G = {"S": [("A", 1), ("B", 4)], "A": [("B", 2), ("C", 5)],
     "B": [("C", 1)], "C": [("G", 3)], "G": []}
def ucs(start, goal):
    frontier = [(0, start, [start])]         # (지금까지 비용, 상태, 경로) 최소 힙
    explored = set()
    while frontier:
        cost, s, path = heapq.heappop(frontier)   # 가장 싼 것을 꺼낸다
        if s in explored: continue           # 더 비싼 사본은 버린다
        explored.add(s)                      # 꺼낸 순간 s 의 최소 비용이 확정
        print(f"pop {s} cost={cost} explored={sorted(explored)}")
        if s == goal: return cost, path
        for t, c in G[s]:
            if t not in explored:
                heapq.heappush(frontier, (cost + c, t, path + [t]))
print(ucs("S", "G"))
def travel(n):                               # 교통 문제를 그래프로
    return {s: ([(s + 1, 1)] if s < n else []) + ([(2 * s, 2)] if 2 * s <= n else [])
            for s in range(1, n + 1)}
G = travel(10)
print(ucs(1, 10))
